import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Support policy","description":"","frontmatter":{},"headers":[],"relativePath":"support.md","filePath":"support.md","lastUpdated":1785077820000}`),a={name:`support.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="support-policy" tabindex="-1">Support policy <a class="header-anchor" href="#support-policy" aria-label="Permalink to “Support policy”">​</a></h1><p>This page defines the environments exercised by CI on <code>main</code>. Beginning with the release candidate, the <a href="./contracts">documented public contracts</a> are frozen. Every listed environment must keep passing the same conformance and packaging gates before a release is published.</p><h2 id="node-js" tabindex="-1">Node.js <a class="header-anchor" href="#node-js" aria-label="Permalink to “Node.js”">​</a></h2><table tabindex="0"><thead><tr><th>Entry point</th><th>Supported versions</th><th>Evidence</th></tr></thead><tbody><tr><td><code>fontmin-rs</code> CLI and Node API</td><td>Node.js 22, 24, and 26</td><td>Full test matrix on Linux, macOS, and Windows</td></tr><tr><td>Native binding packages</td><td>Node-API 8 on the targets below</td><td>Native build plus packed-package smoke tests</td></tr><tr><td><code>@fontmin-rs/wasm</code> tooling</td><td>Node.js 22 or newer</td><td>Typecheck, build, Vitest, and browser package smoke tests</td></tr></tbody></table><p>The published <code>fontmin-rs</code> package declares <code>node &gt;=22.0.0</code>. Newer Node.js majors are best-effort until they are added to the CI matrix. Executable TypeScript, MTS, MJS, and CJS configuration loading also requires Node.js 22 or newer.</p><h2 id="native-platforms" tabindex="-1">Native platforms <a class="header-anchor" href="#native-platforms" aria-label="Permalink to “Native platforms”">​</a></h2><p>The release workflow builds and packages these exact targets:</p><table tabindex="0"><thead><tr><th>Operating system</th><th>CPU</th><th>Runtime</th></tr></thead><tbody><tr><td>macOS</td><td>x64</td><td>Darwin native binding</td></tr><tr><td>macOS</td><td>arm64</td><td>Darwin native binding</td></tr><tr><td>Windows</td><td>x64</td><td>MSVC native binding</td></tr><tr><td>Windows</td><td>arm64</td><td>MSVC native binding</td></tr><tr><td>Linux</td><td>x64</td><td>glibc</td></tr><tr><td>Linux</td><td>x64</td><td>musl</td></tr><tr><td>Linux</td><td>arm64</td><td>glibc</td></tr><tr><td>Linux</td><td>arm64</td><td>musl</td></tr></tbody></table><p>Node <code>runtime: &quot;auto&quot;</code> uses the native package when one of these artifacts can load and falls back to WASM when it cannot. <code>runtime: &quot;native&quot;</code> remains a hard requirement and reports a load error instead of silently changing behavior.</p><h2 id="browser-wasm" tabindex="-1">Browser WASM <a class="header-anchor" href="#browser-wasm" aria-label="Permalink to “Browser WASM”">​</a></h2><p>The browser package is tested in the current Playwright Chromium, Firefox, and WebKit engines. Its public boundary is asynchronous and memory-only: it has no filesystem paths, glob expansion, disk cache, CLI, or arbitrary Node.js plugin hooks.</p><p>Native and WASM execute the same semantic conformance corpus for every built-in transform, preset, output metadata contract, and malformed-input diagnostic. Byte-for-byte output equality is not a compatibility promise.</p><h2 id="rust-toolchains" tabindex="-1">Rust toolchains <a class="header-anchor" href="#rust-toolchains" aria-label="Permalink to “Rust toolchains”">​</a></h2><ul><li><strong>MSRV:</strong> Rust 1.88.0, declared by workspace metadata and checked with <code>cargo check --locked --workspace --all-targets --all-features</code>.</li><li><strong>Pinned development and release toolchain:</strong> Rust 1.97.1, used for formatting, Clippy, tests, coverage, native builds, WASM builds, and releases.</li><li><strong>Fuzzing:</strong> current nightly, isolated to the cargo-fuzz workspace and the scheduled AddressSanitizer job.</li></ul><p>The pinned toolchain is reviewed once per beta/RC preparation or when a dependency requires an upgrade. A toolchain change must be an explicit repository commit and pass the complete release gate. Raising the MSRV before 1.0 requires a changelog entry and migration note; after 1.0 it requires at least a minor release.</p><h2 id="support-boundaries" tabindex="-1">Support boundaries <a class="header-anchor" href="#support-boundaries" aria-label="Permalink to “Support boundaries”">​</a></h2><p>Only environments in this matrix are release-blocking. Other operating systems, CPUs, Node.js versions, and browsers may work through WASM but are best-effort until represented in CI. Report reproducible gaps through the GitHub issue tracker with the runtime, target, input format, and diagnostic output.</p>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};